import React, { useContext, useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";
import { AuthContext } from "../auth/AuthProvider.jsx";
import "../pages/Css/AdminDashboard.css";

export default function AdminDashboard() {
  const navigate = useNavigate();
  const { user, logout, loading } = useContext(AuthContext);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    const checkAuth = async () => {
      try {
        if (!loading) {
          if (!user) {
            navigate("/login", { state: { from: "/admin" } });
            return;
          }
          if (!user.isAdmin) {
            setError("You don't have permission to access the admin dashboard.");
            setTimeout(() => navigate("/"), 2000);
            return;
          }
          setIsLoading(false);
        }
      } catch (err) {
        console.error("Authentication error:", err);
        setError("An error occurred while verifying your permissions.");
        setTimeout(() => navigate("/login"), 2000);
      }
    };

    checkAuth();
  }, [user, loading, navigate]);

  const handleLogout = () => {
    logout();
    navigate("/login");
  };

  const adminFeatures = [
    { 
      title: "Manage Users", 
      description: "View, add, edit, or remove users",
      path: "/admin/users",
      icon: "👥"
    },
    { 
      title: "Manage Posts", 
      description: "Manage all posts and content",
      path: "/admin/posts",
      icon: "📝"
    },
    { 
      title: "Site Analytics", 
      description: "View site statistics and metrics",
      path: "#",
      icon: "📊"
    },
    { 
      title: "Settings", 
      description: "Configure admin settings",
      path: "#",
      icon: "⚙️"
    }
  ];

  if (isLoading || loading) {
    return (
      <div className="admin-dashboard loading">
        <div className="loading-content">
          <div className="spinner"></div>
          <p>Loading Admin Dashboard...</p>
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="admin-dashboard error">
        <div className="error-message">
          <p>{error}</p>
          <p>Redirecting you to the home page...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="admin-dashboard">
      <header className="admin-header">
        <div className="header-content">
          <h1>Admin Dashboard</h1>
          <div className="user-info">
            <span>Welcome, {user?.firstName || 'Admin'}</span>
            <button className="logout-btn" onClick={handleLogout}>
              <span className="btn-icon">🚪</span> Logout
            </button>
          </div>
        </div>
      </header>

      <main className="admin-main">
        <div className="dashboard-overview">
          <div className="overview-card">
            <h3>Total Users</h3>
            <p className="stat">1,234</p>
            <span className="trend up">↑ 12% from last month</span>
          </div>
          <div className="overview-card">
            <h3>Total Posts</h3>
            <p className="stat">5,678</p>
            <span className="trend up">↑ 5% from last month</span>
          </div>
          <div className="overview-card">
            <h3>Active Sessions</h3>
            <p className="stat">42</p>
            <span className="trend down">↓ 2% from yesterday</span>
          </div>
        </div>

        <div className="admin-features">
          <h2>Quick Actions</h2>
          <div className="feature-grid">
            {adminFeatures.map((feature, index) => (
              <div 
                key={index} 
                className="feature-card"
                onClick={() => feature.path !== '#' && navigate(feature.path)}
              >
                <div className="feature-icon">{feature.icon}</div>
                <h3>{feature.title}</h3>
                <p>{feature.description}</p>
              </div>
            ))}
          </div>
        </div>
      </main>

      <footer className="admin-footer">
        <p>© {new Date().getFullYear()} Your App Name. All rights reserved.</p>
        <div className="footer-links">
          <a href="#">Help</a>
          <a href="#">Privacy</a>
          <a href="#">Terms</a>
        </div>
      </footer>
    </div>
  );
}
